async function doCheckWallet(){
  if(needWallet())return;
  const buttons=[...document.querySelectorAll('button')].filter(btn=>/check wallet/i.test(btn.textContent||''));
  const originals=buttons.map(btn=>btn.textContent);
  buttons.forEach(btn=>{btn.disabled=true;btn.textContent='Checking...';});
  toast('Checking wallet for NFTree access and open Seed slots...','ti',6500);
  try{
    const access=await updateNftreeAccess(false);
    if(access){
      toast(`Wallet updated: ${access.nftCount} NFTree NFT${access.nftCount===1?'':'s'}, ${access.availableSeedSlots} plant slot${access.availableSeedSlots===1?'':'s'} ready.`, 'tg', 8500);
      await refreshGarden();
      syncRewardsHub();
    }else{
      toast('Wallet check did not return NFTree access data. Try reconnecting your wallet.', 'tw', 8500);
    }
  }catch(e){
    console.error('doCheckWallet error',e);
    toast(`Wallet check failed: ${e.message||e}`,'td',9000);
  }finally{
    buttons.forEach((btn,i)=>{btn.disabled=false;btn.textContent=originals[i]||'Check Wallet';});
  }
}

